import {
  CircleCheck as CircleCheckIcon,
  CircleX as CircleXIcon,
  Clock as ClockIcon,
  GitBranch as GitBranchIcon,
} from "@designali/icons"

import { Badge } from "@workspace/ui/components/badge"
import { Spinner } from "@workspace/ui/components/spinner"

const deployments = [
  { branch: "main", commit: "a1f9c2e", status: "Ready", time: "2m ago" },
  { branch: "feat/templates", commit: "77be310", status: "Building", time: "Now" },
  {
    branch: "fix/icons-export",
    commit: "c03d8aa",
    status: "Failed",
    time: "18m ago",
  },
  { branch: "chore/blocks", commit: "5e2b1f4", status: "Queued", time: "Now" },
]

export default function DeploymentStatusList() {
  return (
    <div className="w-full max-w-md divide-y border">
      {deployments.map((deploy) => (
        <div key={deploy.commit} className="flex items-center gap-3 p-3">
          <GitBranchIcon className="size-4 shrink-0 text-muted-foreground" />
          <div className="min-w-0 flex-1">
            <p className="truncate text-sm font-medium">{deploy.branch}</p>
            <p className="font-sans text-xs text-muted-foreground">
              {deploy.commit} · {deploy.time}
            </p>
          </div>
          {deploy.status === "Ready" && (
            <Badge className="bg-primary/5 text-chart-3 dark:bg-primary/10 dark:text-chart-1">
              <CircleCheckIcon data-icon="inline-start" />
              Ready
            </Badge>
          )}
          {deploy.status === "Building" && (
            <Badge variant="secondary">
              <Spinner data-icon="inline-start" />
              Building
            </Badge>
          )}
          {deploy.status === "Failed" && (
            <Badge variant="destructive">
              <CircleXIcon data-icon="inline-start" />
              Failed
            </Badge>
          )}
          {deploy.status === "Queued" && (
            <Badge variant="outline">
              <ClockIcon data-icon="inline-start" />
              Queued
            </Badge>
          )}
        </div>
      ))}
    </div>
  )
}
